package com.procurement.controller; import com.procurement.entity.Farmer; import com.procurement.service.FarmerService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/farmers") public class FarmerController {private final FarmerService s; public FarmerController(FarmerService s){this.s=s;} @GetMapping("/me") public Farmer me(Authentication a){return s.me(a.getName());} @PutMapping("/me") public Farmer update(Authentication a,@RequestBody Farmer x){return s.update(a.getName(),x.getFullName(),x.getVillage(),x.getDistrict(),x.getState(),x.getPincode(),x.getAlternatePhone());}}
